import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { BASE_URL } from "@/config/base-url";
import { env } from "@/env";
import { db } from "@/server/db";
import { betterAuthSchema } from "./schema";

/**
 * Main Better Auth configuration
 * @see https://www.better-auth.com/docs/configuration
 *
 * This configuration is only used when Better Auth is enabled
 * via the BETTER_AUTH_ENABLED environment variable.
 */
export const auth = (() => {
  // Better Auth requires a database connection
  if (!db) {
    throw new Error(
      "Better Auth requires a database connection. Please set the DATABASE_URL environment variable."
    );
  }

  return betterAuth({
    database: drizzleAdapter(db, {
      provider: "pg", // PostgreSQL adapter
      schema: betterAuthSchema, // Use our custom schema
    }),

    emailAndPassword: {
      enabled: true,
      requireEmailVerification: true,
    },

    session: {
      expiresIn: 60 * 60 * 24 * 7, // 7 days
      updateAge: 60 * 60 * 24, // 1 day
    },

    user: {
      additionalFields: {
        // Add custom fields to match existing Payload user structure
        firstName: {
          type: "string",
          required: false,
        },
        lastName: {
          type: "string",
          required: false,
        },
        avatar: {
          type: "string",
          required: false,
        },
        role: {
          type: "string",
          required: false,
          defaultValue: "user",
        },
      },
    },

    // Social providers configuration - uses standard OAuth env vars
    socialProviders: {
      // Google OAuth
      ...(env.AUTH_GOOGLE_ID &&
        env.AUTH_GOOGLE_SECRET && {
          google: {
            clientId: env.AUTH_GOOGLE_ID,
            clientSecret: env.AUTH_GOOGLE_SECRET,
          },
        }),

      // GitHub OAuth
      ...(env.AUTH_GITHUB_ID &&
        env.AUTH_GITHUB_SECRET && {
          github: {
            clientId: env.AUTH_GITHUB_ID,
            clientSecret: env.AUTH_GITHUB_SECRET,
          },
        }),

      // Discord OAuth
      ...(env.AUTH_DISCORD_ID &&
        env.AUTH_DISCORD_SECRET && {
          discord: {
            clientId: env.AUTH_DISCORD_ID,
            clientSecret: env.AUTH_DISCORD_SECRET,
          },
        }),
    },

    secret: env?.BETTER_AUTH_SECRET ?? env?.AUTH_SECRET,
    baseURL: env?.BETTER_AUTH_BASE_URL ?? BASE_URL,

    trustedOrigins: [env?.BETTER_AUTH_BASE_URL ?? BASE_URL],

    callbacks: {
      // eslint-disable-next-line @typescript-eslint/require-await -- Better Auth callback signature requires async
      async signUp({ user, account }: { user: any; account: any }) {
        // Custom logic after user signs up
        return { user, account };
      },

      // eslint-disable-next-line @typescript-eslint/require-await -- Better Auth callback signature requires async
      async signIn({ user, account }: { user: any; account: any }) {
        // Custom logic after user signs in
        return { user, account };
      },
    },

    // Advanced options can be configured here if needed
    // See: https://www.better-auth.com/docs/reference/options
  });
})();

export type Auth = typeof auth;

import { boolean, jsonb, pgTable, text, timestamp } from "drizzle-orm/pg-core";

/**
 * Better Auth Database Schema
 *
 * This file defines the database schema for Better Auth.
 * These tables are separate from the existing Auth.js tables
 * to avoid conflicts and allow for coexistence.
 *
 * @see https://www.better-auth.com/docs/concepts/database
 */

// Better Auth User table
export const betterAuthUser = pgTable("better_auth_user", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  name: text("name").notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),

  // Additional fields to match existing Payload user structure
  firstName: text("first_name"),
  lastName: text("last_name"),
  avatar: text("avatar"),
  role: text("role").default("user"),
});

// Better Auth Session table
export const betterAuthSession = pgTable("better_auth_session", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  userId: text("user_id")
    .notNull()
    .references(() => betterAuthUser.id, { onDelete: "cascade" }),
  token: text("token").notNull().unique(),
  expiresAt: timestamp("expires_at").notNull(),
  ipAddress: text("ip_address"),
  userAgent: text("user_agent"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// Better Auth Account table (for OAuth connections)
export const betterAuthAccount = pgTable("better_auth_account", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  userId: text("user_id")
    .notNull()
    .references(() => betterAuthUser.id, { onDelete: "cascade" }),
  accountId: text("account_id").notNull(),
  providerId: text("provider_id").notNull(),
  accessToken: text("access_token"),
  refreshToken: text("refresh_token"),
  idToken: text("id_token"),
  accessTokenExpiresAt: timestamp("access_token_expires_at"),
  refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
  scope: text("scope"),
  password: text("password"), // For email/password auth
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// Better Auth Verification table (for email verification, password reset)
export const betterAuthVerification = pgTable("better_auth_verification", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  identifier: text("identifier").notNull(), // email or phone
  value: text("value").notNull(), // verification token
  expiresAt: timestamp("expires_at").notNull(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// Better Auth Two-Factor Authentication table
export const betterAuthTwoFactor = pgTable("better_auth_two_factor", {
  id: text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  userId: text("user_id")
    .notNull()
    .references(() => betterAuthUser.id, { onDelete: "cascade" }),
  secret: text("secret").notNull(),
  backupCodes: jsonb("backup_codes").$type<string[]>(),
  verified: boolean("verified").notNull().default(false),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// Export all tables for use with Better Auth adapter
export const betterAuthSchema = {
  user: betterAuthUser,
  session: betterAuthSession,
  account: betterAuthAccount,
  verification: betterAuthVerification,
  twoFactor: betterAuthTwoFactor,
};

// Types for TypeScript
export type BetterAuthUser = typeof betterAuthUser.$inferSelect;
export type BetterAuthSession = typeof betterAuthSession.$inferSelect;
export type BetterAuthAccount = typeof betterAuthAccount.$inferSelect;
export type BetterAuthVerification = typeof betterAuthVerification.$inferSelect;
export type BetterAuthTwoFactor = typeof betterAuthTwoFactor.$inferSelect;

// Insert types
export type NewBetterAuthUser = typeof betterAuthUser.$inferInsert;
export type NewBetterAuthSession = typeof betterAuthSession.$inferInsert;
export type NewBetterAuthAccount = typeof betterAuthAccount.$inferInsert;
export type NewBetterAuthVerification = typeof betterAuthVerification.$inferInsert;
export type NewBetterAuthTwoFactor = typeof betterAuthTwoFactor.$inferInsert;

import { env } from "@/env";
import { auth } from "./config";

/**
 * Better Auth Service Layer
 *
 * This service provides utilities for managing Better Auth users,
 * sessions, and integrating with the existing Shipkit architecture.
 */

/**
 * Get the current session from the auth instance
 */
export async function getSession(request: Request) {
  try {
    return await auth.api.getSession({ headers: request.headers });
  } catch (error) {
    console.error("Better Auth: Failed to get session", error);
    return null;
  }
}

/**
 * Check if Better Auth is properly configured
 */
export function isConfigured() {
  return env.NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED;
}

/**
 * Get list of configured OAuth providers for Better Auth
 */
export function getConfiguredProviders(): string[] {
  const providers: string[] = [];

  if (env.NEXT_PUBLIC_FEATURE_AUTH_GOOGLE_ENABLED) providers.push("google");
  if (env.NEXT_PUBLIC_FEATURE_AUTH_GITHUB_ENABLED) providers.push("github");
  if (env.NEXT_PUBLIC_FEATURE_AUTH_DISCORD_ENABLED) providers.push("discord");

  return providers;
}

/**
 * Handle authentication request
 */
export async function handleAuthRequest(request: Request): Promise<Response> {
  try {
    return await auth.handler(request);
  } catch (error) {
    console.error("Better Auth: Failed to handle auth request", error);
    return new Response("Authentication error", { status: 500 });
  }
}

