export type BetterAuthSession = Awaited<ReturnType<typeof getSession>>;
export type BetterAuthUser = BetterAuthSession["user"];

import { env } from "@/env";

/**
 * Better Auth API route handler
 * @see https://www.better-auth.com/docs/installation/nextjs
 *
 * This handles all Better Auth endpoints:
 * - /api/better-auth/sign-in
 * - /api/better-auth/sign-up
 * - /api/better-auth/sign-out
 * - /api/better-auth/session
 * - /api/better-auth/callback/*
 * etc.
 *
 * Only active when Better Auth is properly configured with a database connection.
 */

// Feature gate: Only initialize Better Auth if properly configured
const isBetterAuthConfigured = env.NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED;

export async function GET(request: Request) {
  if (!isBetterAuthConfigured) {
    return new Response("Better Auth is not configured", { status: 404 });
  }

  const { auth } = await import("@/server/better-auth/config");
  return auth.handler(request);
}

export async function POST(request: Request) {
  if (!isBetterAuthConfigured) {
    return new Response("Better Auth is not configured", { status: 404 });
  }

  const { auth } = await import("@/server/better-auth/config");
  return auth.handler(request);
}

"use client";

import { DiscordLogoIcon, GitHubLogoIcon } from "@radix-ui/react-icons";
import { cva } from "class-variance-authority";
import { useState } from "react";
import { toast } from "sonner";
import { Icons } from "@/components/assets/icons";
import {
  useBetterAuthEnabled,
  useBetterAuthProviders,
} from "@/components/providers/better-auth-provider";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { socialSignIn } from "@/lib/better-auth/client";
import { cn } from "@/lib/utils";

const oauthButtonVariants = cva("flex items-center justify-center gap-sm", {
  variants: {
    variant: {
      default: "w-full",
      icons: "w-auto p-2",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

interface BetterAuthOAuthButtonsProps {
  variant?: "default" | "icons";
  className?: string;
}

interface ProviderConfig {
  id: string;
  name: string;
  icon: React.ReactNode;
}

const providerConfigs: Record<string, ProviderConfig> = {
  google: {
    id: "google",
    name: "Google",
    icon: <Icons.google className="h-4 w-4" />,
  },
  github: {
    id: "github",
    name: "GitHub",
    icon: <GitHubLogoIcon className="h-4 w-4" />,
  },
  discord: {
    id: "discord",
    name: "Discord",
    icon: <DiscordLogoIcon className="h-4 w-4" />,
  },
};

/**
 * Better Auth OAuth Buttons Component
 *
 * This component renders OAuth sign-in buttons for Better Auth providers.
 * It only renders when Better Auth is enabled and configured providers are available.
 */
export function BetterAuthOAuthButtons({
  variant = "default",
  className,
}: BetterAuthOAuthButtonsProps) {
  const isBetterAuthEnabled = useBetterAuthEnabled();
  const availableProviders = useBetterAuthProviders();
  const [loadingProvider, setLoadingProvider] = useState<string | null>(null);

  // Don't render if Better Auth is not enabled or no providers available
  if (!isBetterAuthEnabled || availableProviders.length === 0) {
    return null;
  }

  const handleSignIn = async (providerId: string) => {
    try {
      setLoadingProvider(providerId);

      // Use Better Auth social sign-in
      switch (providerId) {
        case "google":
          await socialSignIn.google();
          break;
        case "github":
          await socialSignIn.github();
          break;
        case "discord":
          await socialSignIn.discord();
          break;
        default:
          throw new Error(`Unsupported provider: ${providerId}`);
      }
    } catch (error) {
      console.error("Better Auth: Sign-in failed", error);
      toast.error(`Failed to sign in with ${providerConfigs[providerId]?.name ?? providerId}`);
    } finally {
      setLoadingProvider(null);
    }
  };

  return (
    <div
      className={cn(
        "flex w-full gap-xs",
        variant === "icons" ? "flex-row justify-center" : "flex-col items-stretch",
        className
      )}
    >
      {availableProviders.map((providerId) => {
        const config = providerConfigs[providerId];
        if (!config) return null;

        const isLoading = loadingProvider === providerId;

        const button = (
          <Button
            variant="outline"
            type="button"
            onClick={() => handleSignIn(providerId)}
            disabled={isLoading}
            className={oauthButtonVariants({ variant })}
          >
            {variant === "default" && (
              <span>{isLoading ? "Signing in..." : `Sign in with ${config.name}`}</span>
            )}
            {config.icon}
          </Button>
        );

        return (
          <div key={providerId}>
            {variant === "icons" ? (
              <Tooltip>
                <TooltipTrigger asChild>{button}</TooltipTrigger>
                <TooltipContent>
                  <p>Sign in with {config.name}</p>
                </TooltipContent>
              </Tooltip>
            ) : (
              button
            )}
          </div>
        );
      })}
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { env } from "@/env";

interface BetterAuthProviderProps {
  children: ReactNode;
}

/**
 * Better Auth Provider Component
 *
 * This component provides Better Auth context to the application
 * when Better Auth is enabled. It provides utilities and hooks
 * for Better Auth throughout the app.
 *
 * Only renders when Better Auth is enabled via environment variables.
 */
export function BetterAuthProvider({ children }: BetterAuthProviderProps) {
  // For now, just render children - Better Auth client is available globally
  return <>{children}</>;
}

/**
 * Hook to check if Better Auth is enabled and available
 */
export function useBetterAuthEnabled() {
  return env.NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED;
}

/**
 * Hook to get Better Auth providers that are enabled
 */
export function useBetterAuthProviders() {
  const isBetterAuthEnabled = useBetterAuthEnabled();

  if (!isBetterAuthEnabled) {
    return [];
  }

  const providers = [];

  if (env.NEXT_PUBLIC_FEATURE_AUTH_GOOGLE_ENABLED) {
    providers.push("google");
  }

  if (env.NEXT_PUBLIC_FEATURE_AUTH_GITHUB_ENABLED) {
    providers.push("github");
  }

  if (env.NEXT_PUBLIC_FEATURE_AUTH_DISCORD_ENABLED) {
    providers.push("discord");
  }

  return providers;
}
